1	using System.Globalization;
2	using System.Text;
3	
4	namespace TutorFlow.Api;
5	
6	// Decisiones de permisos en código puro. Nunca consulta al modelo (RN-07).
7	public static class Permisos
8	{
9	    public static Usuario? ResolverUsuario(Datos datos, string rol, string id) => datos.BuscarUsuario(rol, id);
10	
11	    // Reutilizable por las herramientas (T4): estudiante solo su id; coordinador, estudiantes de su programa.
12	    public static bool PuedeVerEstudiante(Datos datos, Usuario usuario, string estudianteId)
13	    {
14	        if (usuario.Rol == "estudiante") return usuario.Id == estudianteId;
15	        if (usuario.Rol != "coordinador") return false;
16	        var e = datos.Estudiantes.FirstOrDefault(x => x.Id == estudianteId);
17	        return e != null && e.Programa == usuario.Programa;
18	    }
19	
20	    // true si la pregunta menciona (por id o nombre) a algún estudiante que el usuario no puede ver.
21	    // Las apariciones que caen por completo dentro del tramo del propio nombre completo o del propio id se ignoran;
22	    // una aparición que se extiende más allá de ese tramo (o aparece fuera) cuenta.
23	    // Decisión SPEC §9: si el nombre de un tercero es subsecuencia contigua del nombre propio, dentro del tramo
24	    // propio no se detecta (es el usuario nombrándose a sí mismo); solo cuenta si aparece fuera o se extiende más allá.
25	    public static bool MencionaTercero(Datos datos, Usuario usuario, string pregunta)
26	    {
27	        var tokens = Tokenizar(pregunta);
28	        var propio = new bool[tokens.Count];
29	        foreach (var (i, n) in Apariciones(tokens, Tokenizar(usuario.Nombre)))
30	            for (var k = i; k < i + n; k++) propio[k] = true;
31	        foreach (var (i, n) in AparicionesId(tokens, string.Concat(Tokenizar(usuario.Id))))
32	            for (var k = i; k < i + n; k++) propio[k] = true;
33	
34	        bool Fuera(int i, int n)
35	        {
36	            for (var k = i; k < i + n; k++) if (!propio[k]) return true;
37	            return false;
38	        }
39	
40	        foreach (var e in datos.Estudiantes)
41	        {
42	            if (usuario.Rol == "estudiante" && e.Id == usuario.Id) continue;
43	            if (PuedeVerEstudiante(datos, usuario, e.Id)) continue;
44	            var partes = Tokenizar(e.Nombre);
45	            if (Apariciones(tokens, partes).Any(a => Fuera(a.Inicio, a.Largo))) return true;
46	            if (AparicionesId(tokens, string.Concat(Tokenizar(e.Id))).Any(a => Fuera(a.Inicio, a.Largo))) return true;
47	            if (partes.Count > 0)
48	                for (var i = 0; i < tokens.Count; i++)
49	                    if (tokens[i] == partes[0] && !propio[i]) return true;
50	        }
51	        return false;
52	    }
53	
54	    static List<(int Inicio, int Largo)> Apariciones(List<string> tokens, List<string> seq)
55	    {
56	        var r = new List<(int, int)>();
57	        if (seq.Count == 0) return r;
58	        for (var i = 0; i + seq.Count <= tokens.Count; i++)
59	            if (tokens.Skip(i).Take(seq.Count).SequenceEqual(seq)) r.Add((i, seq.Count));
60	        return r;
61	    }
62	
63	    // El id colapsado (solo letras y dígitos) coincide con un token o con tokens consecutivos concatenados.
64	    static List<(int Inicio, int Largo)> AparicionesId(List<string> tokens, string clave)
65	    {
66	        var r = new List<(int, int)>();
67	        if (clave.Length == 0) return r;
68	        for (var i = 0; i < tokens.Count; i++)
69	        {
70	            var acc = "";
71	            for (var j = i; j < tokens.Count; j++)
72	            {
73	                acc += tokens[j];
74	                if (acc == clave) { r.Add((i, j - i + 1)); break; }
75	                if (!clave.StartsWith(acc, StringComparison.Ordinal)) break;
76	            }
77	        }
78	        return r;
79	    }
80	
81	    // FormKD, sin categorías Cf/Mn, minúsculas; luego secuencias de letras/dígitos.
82	    static List<string> Tokenizar(string? s)
83	    {
84	        var sb = new StringBuilder();
85	        foreach (var c in (s ?? "").Normalize(NormalizationForm.FormKD))
86	        {
87	            var cat = CharUnicodeInfo.GetUnicodeCategory(c);
88	            if (cat == UnicodeCategory.Format || cat == UnicodeCategory.NonSpacingMark) continue;
89	            sb.Append(char.IsLetterOrDigit(c) ? char.ToLowerInvariant(c) : ' ');
90	        }
91	        return sb.ToString().Split(' ', StringSplitOptions.RemoveEmptyEntries).ToList();
92	    }
93	}
