1	using System.Text.Json;
2	
3	namespace TutorFlow.Api;
4	
5	public record Usuario(string Rol, string Id, string Nombre, string Programa);
6	
7	// Única clase que conoce el formato de los JSON de datos. Cada registro se clasifica por su forma.
8	public class Datos
9	{
10	    public IReadOnlyList<Usuario> Estudiantes { get; }
11	    public IReadOnlyList<Usuario> Coordinadores { get; }
12	    public IReadOnlyList<JsonElement> Notas { get; }
13	    public IReadOnlyList<JsonElement> Asistencia { get; }
14	
15	    public Datos(string carpeta)
16	    {
17	        var est = new List<Usuario>();
18	        var coo = new List<Usuario>();
19	        var notas = new List<JsonElement>();
20	        var asis = new List<JsonElement>();
21	        if (!Directory.Exists(carpeta))
22	            throw new DirectoryNotFoundException("La carpeta de datos de la API no existe; no se puede arrancar sin ella.");
23	        foreach (var archivo in Directory.GetFiles(carpeta, "*.json").OrderBy(f => f, StringComparer.Ordinal))
24	        {
25	            var nombreArchivo = Path.GetFileName(archivo);
26	            using var doc = JsonDocument.Parse(File.ReadAllText(archivo));
27	            if (doc.RootElement.ValueKind != JsonValueKind.Array) continue;
28	            var usuariosArchivo = new List<(JsonElement El, bool ConSemestre)>();
29	            foreach (var e in doc.RootElement.EnumerateArray())
30	            {
31	                if (e.ValueKind != JsonValueKind.Object) continue;
32	                var c = e.Clone();
33	                if (Tiene(c, "estudianteId") && Tiene(c, "definitiva")) notas.Add(c);
34	                else if (Tiene(c, "estudianteId") && Tiene(c, "inasistencias")) asis.Add(c);
35	                else if (Tiene(c, "id") && !Tiene(c, "estudianteId")) usuariosArchivo.Add((c, Tiene(c, "semestre")));
36	                else if (!Tiene(c, "estudianteId") && (Tiene(c, "nombre") || Tiene(c, "programa")))
37	                    throw new InvalidDataException($"Registro de usuario sin 'id' en '{nombreArchivo}'.");
38	            }
39	            if (usuariosArchivo.Count == 0) continue;
40	            // RN-14: la forma es una decision por archivo, nunca por la ausencia de un campo en un registro.
41	            var esEstudiantes = usuariosArchivo[0].ConSemestre;
42	            if (usuariosArchivo.Any(u => u.ConSemestre != esEstudiantes))
43	                throw new InvalidDataException($"El archivo '{nombreArchivo}' mezcla registros de usuario de formas distintas.");
44	            foreach (var (c, _) in usuariosArchivo)
45	            {
46	                var id = Texto(c, "id");
47	                var programa = Texto(c, "programa");
48	                var nombre = Texto(c, "nombre");
49	                if (string.IsNullOrWhiteSpace(id) || string.IsNullOrWhiteSpace(programa) || string.IsNullOrWhiteSpace(nombre))
50	                    throw new InvalidDataException(
51	                        $"Registro de usuario invalido en '{nombreArchivo}': 'id', 'programa' y 'nombre' deben ser texto no vacio.");
52	                (esEstudiantes ? est : coo).Add(new Usuario(esEstudiantes ? "estudiante" : "coordinador", id, nombre, programa));
53	            }
54	        }
55	        var duplicado = est.Concat(coo).GroupBy(u => u.Id).FirstOrDefault(g => g.Count() > 1);
56	        if (duplicado != null)
57	            throw new InvalidDataException("Hay un id de usuario repetido (en el mismo rol o en ambos roles); los datos son inconsistentes.");
58	        Estudiantes = est;
59	        Coordinadores = coo;
60	        Notas = notas;
61	        Asistencia = asis;
62	    }
63	
64	    static bool Tiene(JsonElement e, string p) => e.TryGetProperty(p, out _);
65	    static string? Texto(JsonElement e, string p) =>
66	        e.TryGetProperty(p, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;
67	
68	    public Usuario? BuscarUsuario(string rol, string id) =>
69	        (rol == "estudiante" ? Estudiantes : rol == "coordinador" ? Coordinadores : [])
70	            .FirstOrDefault(u => u.Id == id);
71	}
