17	public sealed class EntornoAsistente : IDisposable
18	{
19	    public const string Url = "/api/asistente/preguntar";
20	    private readonly WebApplicationFactory<Program> _fabrica;
21	    private readonly string? _temporal;
22	    public HttpClient Cliente { get; }
23	    public FakeLlmClient Llm { get; }
24	
25	    public EntornoAsistente(FakeLlmClient llm, IDictionary<string, string[]>? extra = null)
26	    {
27	        Llm = llm;
28	        string ruta = Fabrica.RutaFixtures;
29	        if (extra != null)
30	        {
31	            _temporal = Path.Combine(Path.GetTempPath(), "tutorflow-asist-" + Guid.NewGuid().ToString("N"));
32	            foreach (var sub in new[] { "api", "reglamento" })
33	            {
34	                Directory.CreateDirectory(Path.Combine(_temporal, sub));
35	                foreach (var f in Directory.GetFiles(Path.Combine(Fabrica.RutaFixtures, sub)))
36	                    File.Copy(f, Path.Combine(_temporal, sub, Path.GetFileName(f)));
37	            }
38	            foreach (var (archivo, registros) in extra)
39	            {
40	                var p = Path.Combine(_temporal, "api", archivo);
41	                var t = File.ReadAllText(p).TrimEnd();
42	                t = t.Substring(0, t.LastIndexOf(']')).TrimEnd() + "," + string.Join(",", registros) + "]";
43	                File.WriteAllText(p, t);
44	            }
45	            ruta = _temporal;
46	        }
47	        _fabrica = new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
48	        {
49	            b.UseSetting("Datos:Ruta", ruta);
50	            b.UseSetting("LLM_API_KEY", "llave-falsa-de-prueba");
51	            b.ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(new Dictionary<string, string?>
52	            {
53	                ["Datos:Ruta"] = ruta,
54	                ["LLM_API_KEY"] = "llave-falsa-de-prueba",
55	            }));
56	            b.ConfigureTestServices(sv => { sv.RemoveAll<ILlmClient>(); sv.AddSingleton<ILlmClient>(llm); });
57	        });
58	        Cliente = _fabrica.CreateClient();
59	        Cliente.Timeout = TimeSpan.FromSeconds(60);
60	    }
61	
62	    public async Task<(HttpStatusCode Codigo, string Cuerpo)> Preguntar(string pregunta, string rol, string id)
63	    {
64	        var json = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
65	        var r = await Cliente.PostAsync(Url, new StringContent(json, Encoding.UTF8, "application/json"));
66	        return (r.StatusCode, await r.Content.ReadAsStringAsync());
67	    }
68	
69	    public void Dispose()
70	    {
71	        Cliente.Dispose();
72	        _fabrica.Dispose();
73	        if (_temporal != null) try { Directory.Delete(_temporal, true); } catch { }
74	    }
75	}
