1	using TutorFlow.Api.Llm;
2	
3	namespace TutorFlow.Tests;
4	
5	public record InvocacionLlm(string Sistema, IReadOnlyList<LlmMensaje> Mensajes, IReadOnlyList<LlmHerramienta> Herramientas);
6	
7	/// <summary>
8	/// Modelo falso guionado: cada paso recibe los mensajes de la vuelta y devuelve la respuesta. Registra cada invocación.
9	/// Si el guion se agota lanza (el asistente debe devolver 503), salvo que se use RepetirUltimo.
10	/// </summary>
11	public class FakeLlmClient : ILlmClient
12	{
13	    private readonly Queue<Func<IReadOnlyList<LlmMensaje>, LlmRespuesta>> _pasos = new();
14	    private Func<IReadOnlyList<LlmMensaje>, LlmRespuesta>? _ultimo;
15	    public bool RepetirUltimo { get; set; }
16	    public List<InvocacionLlm> Invocaciones { get; } = [];
17	    public int Llamadas => Invocaciones.Count;
18	
19	    public FakeLlmClient Paso(Func<IReadOnlyList<LlmMensaje>, LlmRespuesta> paso) { _pasos.Enqueue(paso); return this; }
20	
21	    public FakeLlmClient Herramienta(string nombre, string argumentosJson, int entrada = 0, int salida = 0) =>
22	        Paso(_ => new LlmRespuesta(null,
23	            [new LlmLlamadaHerramienta("call-" + Guid.NewGuid().ToString("N")[..8], nombre, argumentosJson)],
24	            new LlmUso(entrada, salida)));
25	
26	    public FakeLlmClient Texto(string texto, int entrada = 0, int salida = 0) =>
27	        Paso(_ => new LlmRespuesta(texto, [], new LlmUso(entrada, salida)));
28	
29	    public FakeLlmClient Final(string respuesta, string citasJson = "[]", int entrada = 0, int salida = 0) =>
30	        Texto("{\"respuesta\":" + System.Text.Json.JsonSerializer.Serialize(respuesta) + ",\"citas\":" + citasJson + "}",
31	            entrada, salida);
32	
33	    public FakeLlmClient Lanza(Exception e) => Paso(_ => throw e);
34	
35	    public Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
36	        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
37	    {
38	        lock (Invocaciones) Invocaciones.Add(new InvocacionLlm(sistema, mensajes.ToList(), herramientas.ToList()));
39	        Func<IReadOnlyList<LlmMensaje>, LlmRespuesta> paso;
40	        if (_pasos.Count > 0) { paso = _pasos.Dequeue(); _ultimo = paso; }
41	        else if (RepetirUltimo && _ultimo != null) paso = _ultimo;
42	        else throw new InvalidOperationException("Guion del modelo falso agotado.");
43	        return Task.FromResult(paso(mensajes));
44	    }
45	
46	    /// <summary>Contenido concatenado de todos los mensajes "tool" que recibió el modelo en cualquier vuelta.</summary>
47	    public string ResultadosHerramienta() =>
48	        string.Join("\n", Invocaciones.SelectMany(i => i.Mensajes).Where(m => m.Rol == "tool").Select(m => m.Contenido));
49	
50	    /// <summary>Todo lo que el modelo vio (sistema + mensajes) en todas las vueltas.</summary>
51	    public string TodoLoVisto() =>
52	        string.Join("\n", Invocaciones.Select(i => i.Sistema + "\n" + string.Join("\n", i.Mensajes.Select(m => m.Contenido))));
53	}
